import streamlit as st
import streamlit.components.v1 as components

st.set_page_config(page_title="For Sanjana 💗 | From Baldeep", page_icon="💗", layout="wide", initial_sidebar_state="collapsed")

st.markdown("""<style>
header[data-testid="stHeader"], footer, #MainMenu {display:none!important}
.stApp {background:#0d0717;}
.block-container {padding:0!important;max-width:100%!important}
iframe {display:block;border:0!important}
</style>""", unsafe_allow_html=True)

html = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Great+Vibes&family=Playfair+Display:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
:root{--pink:#f3a6bc;--light:#fff2f3;--gold:#eecb8f;--dark:#10091c}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;min-height:100vh;background:var(--dark);color:var(--light);font-family:'DM Sans',sans-serif;overflow-x:hidden}body:before{content:'';position:fixed;inset:0;background:radial-gradient(circle at 18% 15%,#6d2c59aa,transparent 34%),radial-gradient(circle at 86% 68%,#4a2d65aa,transparent 38%),linear-gradient(145deg,#170d25,#0a0615 70%);z-index:-3}.stars{position:fixed;inset:0;z-index:-2;pointer-events:none}.star{position:absolute;width:2px;height:2px;background:#ffe7dd;border-radius:50%;animation:twinkle var(--dur) ease-in-out infinite alternate;opacity:.6}@keyframes twinkle{to{opacity:.1;transform:scale(.5)}}.float{position:fixed;pointer-events:none;z-index:-1;opacity:0;animation:rise linear forwards;font-size:20px}@keyframes rise{0%{transform:translateY(0) rotate(-10deg);opacity:0}15%{opacity:.7}85%{opacity:.6}100%{transform:translateY(-110vh) rotate(35deg);opacity:0}}.wrap{max-width:1000px;margin:auto;padding:0 22px}.hero{min-height:92vh;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;position:relative;padding:80px 20px}.eyebrow{letter-spacing:4px;text-transform:uppercase;color:#f6cbd5;font-size:11px;font-weight:700}.date{margin-top:14px;font-size:14px;color:#d3b9c8;letter-spacing:1px}.moon{font-size:40px;filter:drop-shadow(0 0 25px #ffd4ad77);margin-bottom:18px}.hero h1{font:500 clamp(64px,12vw,135px)/1.05 'Great Vibes',cursive;margin:28px 0 8px;color:#ffd7de;text-shadow:0 0 40px #ff9fb26a}.hero h2{font:500 clamp(27px,5vw,47px)/1.2 'Playfair Display',serif;margin:6px 0 25px}.hero p{font-size:16px;color:#e5cbd8;line-height:1.8;max-width:560px}.pill{border:1px solid #ffc4cf88;background:linear-gradient(120deg,#e88ba9,#bf5f88);color:#fff;border-radius:99px;padding:15px 29px;box-shadow:0 10px 32px #d34e8a46;cursor:pointer;font-weight:700;font-size:14px;transition:.25s;display:inline-flex;align-items:center;gap:9px;margin-top:22px}.pill:hover{transform:translateY(-3px);box-shadow:0 14px 35px #e76f9b77}.pill.secondary{background:#ffffff12;border-color:#ffc5cf55;box-shadow:none}.scroll{position:absolute;bottom:22px;color:#bba2b2;font-size:12px;letter-spacing:2px;animation:bob 2s infinite}@keyframes bob{50%{transform:translateY(8px)}}section{padding:90px 0;text-align:center}.section-title{font:500 clamp(32px,5vw,49px)/1.25 'Playfair Display',serif;margin:12px 0 16px}.sub{color:#cbb5c5;line-height:1.8;max-width:580px;margin:0 auto 35px}.line{width:80px;height:1px;background:linear-gradient(90deg,transparent,var(--gold),transparent);margin:0 auto 24px}.glass{background:linear-gradient(135deg,#fff9 0%,#ffffff09 2%,#ffffff05 100%);border:1px solid #f8d6e533;border-radius:25px;box-shadow:0 30px 80px #0004;backdrop-filter:blur(10px)}.letter{max-width:750px;margin:auto;padding:clamp(25px,6vw,65px);text-align:left;position:relative}.letter:before{content:'❝';position:absolute;top:9px;right:32px;font:90px Georgia;color:#eeb1c144}.letter h3{font:42px 'Great Vibes',cursive;color:#ffc5d5;margin:0 0 22px}.letter p{font:17px/2 'Playfair Display',serif;color:#f2dce4}.signature{text-align:right;font:36px 'Great Vibes',cursive;color:var(--pink);margin-top:25px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:17px;text-align:left}.reason{min-height:210px;padding:29px 25px;display:flex;flex-direction:column;justify-content:space-between;cursor:pointer;transition:transform .3s,background .3s;position:relative}.reason:hover{transform:translateY(-6px);background:#ffffff13}.reason .number{color:var(--gold);font:15px 'Playfair Display',serif}.reason .emoji{font-size:34px}.reason .reveal{font:22px/1.4 'Playfair Display',serif;color:#ffe4eb}.reason .hint{font-size:12px;color:#c9adbe}.gift-box{margin:36px auto 0;width:min(310px,85vw);height:245px;display:grid;place-items:center;cursor:pointer;position:relative;transition:transform .3s}.gift-box:hover{transform:scale(1.05)}.gift{font-size:145px;filter:drop-shadow(0 15px 35px #ea72a955);animation:bob 2s infinite}.gift-text{font-size:13px;letter-spacing:2px;color:#e8b9ce;margin-top:7px}.hidden{display:none!important}.surprise{animation:appear 1s ease both}@keyframes appear{from{opacity:0;transform:translateY(30px)}to{opacity:1;transform:translateY(0)}}.big-heart{font-size:65px;animation:pulse 1.5s ease-in-out infinite}@keyframes pulse{50%{transform:scale(1.2)}}.final-message{font:500 clamp(30px,5vw,50px)/1.4 'Playfair Display',serif;color:#ffe0e8;max-width:760px;margin:25px auto}.final-message span{font-family:'Great Vibes',cursive;color:#ffadc7;font-size:1.5em}.cake{font-size:74px;margin:17px}.footer{padding:75px 0 45px;text-align:center;color:#cbaabb;font-size:13px}.footer strong{color:#ffe0e8}.badge{display:inline-block;border:1px solid #f5b9c955;border-radius:40px;padding:11px 19px;color:#edc3d3;font-size:12px;letter-spacing:1px}.confetti{position:fixed;top:-20px;width:9px;height:13px;z-index:50;pointer-events:none;animation:fall var(--t) linear forwards}@keyframes fall{to{transform:translate(var(--x),110vh) rotate(780deg);opacity:.2}}.counter{display:flex;gap:10px;justify-content:center;margin:22px auto;flex-wrap:wrap}.count-item{min-width:76px;padding:13px;border-radius:14px;background:#ffffff0e;border:1px solid #ffffff20}.count-item b{display:block;font:28px 'Playfair Display',serif;color:#ffd5df}.count-item small{font-size:10px;color:#cab0bf;letter-spacing:1px}.divider{height:1px;background:linear-gradient(90deg,transparent,#f4bac844,transparent)}@media(max-width:690px){.cards{grid-template-columns:1fr 1fr}.reason{min-height:190px;padding:22px}.reason .reveal{font-size:19px}.hero{min-height:90vh}.letter p{font-size:15px}}@media(max-width:440px){.cards{grid-template-columns:1fr}.reason{min-height:145px}.hero h1{font-size:75px}section{padding:65px 0}}
</style></head><body><div class="stars" id="stars"></div>
<main><div class="hero" id="top"><div class="moon">☾ ✦</div><div class="eyebrow">A LITTLE UNIVERSE MADE JUST FOR YOU</div><div class="date">29 OCTOBER · A DAY THE WORLD BECAME MORE BEAUTIFUL</div><h1>Sanjana</h1><h2>Happy Birthday, my love ♡</h2><p>Some people make the world brighter just by being in it. For me, that person is you. Tonight, every little star has a wish for you.</p><button class="pill" onclick="document.getElementById('letter').scrollIntoView({behavior:'smooth'});burst(30)">Open your birthday surprise ✨</button><div class="scroll">SCROLL TO FEEL THE MAGIC ↓</div></div>
<div class="wrap"><div class="divider"></div><section id="letter"><div class="eyebrow">FIRST, A LETTER FROM MY HEART</div><h2 class="section-title">To the girl who means everything</h2><div class="line"></div><div class="letter glass"><h3>My dearest Sanjana,</h3><p>Happy Birthday, meri jaan. ❤️</p><p>If I could give you one thing in this world, it would be the ability to see yourself through my eyes. Then you'd know just how special, beautiful, and irreplaceable you are to me.</p><p>You make ordinary days feel like celebrations, and even the smallest moments feel like memories I want to keep forever. Your smile is my favourite sight, your happiness is my favourite wish, and loving you is my favourite part of life.</p><p>On your birthday, I wish you a thousand reasons to smile, the courage to chase every dream, and a lifetime of love, laughter, and beautiful surprises. Through every season, I hope I get to be the person cheering for you, holding your hand, and reminding you how loved you are.</p><p>Thank you for being you. I love you more than these words will ever be able to say.</p><div class="signature">Forever yours,<br>Baldeep ♡</div></div></section>
<div class="divider"></div><section id="reasons"><div class="eyebrow">A FEW OF A MILLION REASONS</div><h2 class="section-title">The little things I adore about you</h2><p class="sub">Tap each card. Every one holds a tiny piece of what makes you so special to me.</p><div class="cards" id="cards"></div></section>
<div class="divider"></div><section id="wish"><div class="eyebrow">MAKE A WISH, BEAUTIFUL</div><h2 class="section-title">The universe is listening ✨</h2><p class="sub">Close your eyes, take a deep breath, and think of one beautiful wish. Then tap the gift.</p><div id="giftBox" class="gift-box" role="button" tabindex="0" aria-label="Open birthday gift" onclick="openGift()" onkeydown="if(event.key==='Enter')openGift()"><div><div class="gift">🎁</div><div class="gift-text">TAP TO UNWRAP YOUR SURPRISE</div></div></div><div class="surprise hidden" id="surprise"><div class="big-heart">💗</div><div class="final-message">No matter how many birthdays come and go, <span>I'll always choose you.</span></div><p class="sub">You are my favourite person, my safest place, and my most beautiful adventure.</p><div class="cake">🎂</div><h2 class="section-title">Happy 25th Birthday, Sanjana!</h2><p class="sub">With all my love, today and every day. — Baldeep Singh</p><button class="pill" onclick="burst(130)">One more shower of love 💖</button></div></section><div class="divider"></div><div class="footer"><div class="badge">EST. 29 OCTOBER 2001 · A STAR WAS BORN ✧</div><p>Made with endless love, just for <strong>Sanjana Bhola</strong></p><p>From your <strong>Baldeep Singh</strong> ♡</p><button class="pill secondary" onclick="document.getElementById('top').scrollIntoView({behavior:'smooth'})">Back to the stars ↑</button></div></div></main>
<script>
const stars=document.getElementById('stars');for(let i=0;i<115;i++){let s=document.createElement('i');s.className='star';s.style.left=Math.random()*100+'%';s.style.top=Math.random()*100+'%';s.style.width=s.style.height=(Math.random()*2+1)+'px';s.style.setProperty('--dur',(Math.random()*3+1)+'s');stars.appendChild(s)}
const reasons=[['🌷','Your smile makes everything feel lighter.'],['✨','You turn simple moments into magic.'],['🫶','The warmth and kindness in your heart.'],['🌙','Being with you feels like coming home.'],['💫','The way you make me want to be better.'],['💗','Because you are wonderfully, beautifully YOU.']];
const cards=document.getElementById('cards');reasons.forEach((r,i)=>{let el=document.createElement('div');el.className='reason glass';el.setAttribute('role','button');el.setAttribute('tabindex','0');el.innerHTML=`<span class="number">0${i+1} / 06</span><span class="emoji">${r[0]}</span><span class="hint">Tap to reveal ♡</span>`;let show=()=>{el.innerHTML=`<span class="number">0${i+1} / 06</span><span class="emoji">${r[0]}</span><span class="reveal">${r[1]}</span>`;el.style.background='#ef96b520';};el.onclick=show;el.onkeydown=e=>{if(e.key==='Enter')show()};cards.appendChild(el)});
function burst(n=80){const colors=['#ffadc8','#ffd19c','#fff5db','#ce9beb','#ff759b'];for(let i=0;i<n;i++){let c=document.createElement('i');c.className='confetti';c.style.left=Math.random()*100+'vw';c.style.background=colors[Math.floor(Math.random()*colors.length)];c.style.borderRadius=Math.random()>.5?'50%':'2px';c.style.setProperty('--t',(2.5+Math.random()*3)+'s');c.style.setProperty('--x',((Math.random()-.5)*400)+'px');document.body.appendChild(c);setTimeout(()=>c.remove(),6500)}}
let opened=false;function openGift(){if(opened){burst(80);return}opened=true;document.getElementById('giftBox').classList.add('hidden');document.getElementById('surprise').classList.remove('hidden');burst(180);setTimeout(()=>burst(80),600)}
setInterval(()=>{if(document.hidden)return;let h=document.createElement('div');h.className='float';h.textContent=Math.random()>.5?'♡':'✦';h.style.left=Math.random()*100+'vw';h.style.bottom='-40px';h.style.animationDuration=(8+Math.random()*7)+'s';h.style.color='#f5adcd';document.body.appendChild(h);setTimeout(()=>h.remove(),16000)},1800);
</script></body></html>'''

components.html(html, height=1050, scrolling=True)
